INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2650, 'revenue', '/ˈrevənjuː/', 'noun', '{"zh-TW":["收入；營收","營收"],"en":["income, especially of a company or organization","income from business activities","income earned by a company"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"venue","meaning":"come (來)"},"logic":"回來的錢，即「收入」。"}', 'annual revenue / revenue growth / generate revenue; revenue stream / revenue growth / total revenue', '[{"en":"The company''s annual revenue exceeded $1 billion.","zh-TW":"公司年營收超過10億美元。"},{"en":"Online sales are a major source of revenue.","zh-TW":"線上銷售是主要收入來源。"},{"en":"Annual revenue reached $50 million.","zh-TW":"年營收達到五千萬美元。"},{"en":"The new product line generates significant revenue.","zh-TW":"新產品線產生了可觀收入。"},{"en":"Total revenue exceeded expectations.","zh-TW":"總營收超出預期。"},{"en":"We need to diversify revenue streams.","zh-TW":"我們需要多元化收入來源。"}]', NULL, NULL, 3, 2650, 208),
(2651, 'reverse', '/rɪˈvɜːrs/', 'verb', '{"zh-TW":["逆轉；撤銷"],"en":["to change to the opposite"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"verse","meaning":"turn (轉)"}}', 'reverse a decision / reverse the trend / in reverse', '[{"en":"The board reversed its earlier decision.","zh-TW":"董事會撤銷了先前的決定。"},{"en":"We need to reverse this downward trend.","zh-TW":"我們需要逆轉下降趨勢。"}]', '{"noun":"reversal","adjective":"reversible"}', NULL, 3, 2651, NULL),
(2652, 'review', '/rɪˈvjuː/', 'noun', '{"zh-TW":["審查；評論"],"en":["an examination; an assessment"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"view","meaning":"see (看)"}}', 'performance review / under review / review process', '[{"en":"The application is currently under review.","zh-TW":"申請目前正在審查中。"},{"en":"Annual performance reviews start next week.","zh-TW":"年度績效考核下週開始。"}]', '{"verb":"review","noun":"reviewer"}', NULL, 2, 2652, 60),
(2653, 'revise', '/rɪˈvaɪz/', 'verb', '{"zh-TW":["修改；修訂","修訂"],"en":["to change or correct"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"vise","meaning":"see (看)"}}', 'revise the budget / revise upward / revised edition; revise the plan / revised estimate / subject to revision', '[{"en":"We need to revise the budget estimates.","zh-TW":"我們需要修改預算估計。"},{"en":"The forecast has been revised upward.","zh-TW":"預測已被上調修正。"},{"en":"The policy was revised last quarter.","zh-TW":"政策在上季度進行了修訂。"},{"en":"All figures are subject to revision.","zh-TW":"所有數字可能會修訂。"}]', '{"noun":"revision"}', NULL, 2, 2653, 209),
(2654, 'revolve', '/rɪˈvɒlv/', 'verb', '{"zh-TW":["圍繞；旋轉"],"en":["to move in a circle; to center on"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"volve","meaning":"roll (滾動)"}}', 'revolve around / revolving door / revolving credit', '[{"en":"The discussion revolved around cost reduction.","zh-TW":"討論圍繞著降低成本進行。"},{"en":"Our strategy revolves around innovation.","zh-TW":"我們的策略以創新為中心。"}]', '{"adjective":"revolving","noun":"revolution"}', NULL, 3, 2654, NULL),
(2655, 'reward', '/rɪˈwɔːrd/', 'noun', '{"zh-TW":["獎勵；報酬","獎勵"],"en":["something given in recognition","to give something good in return for effort"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ward","meaning":"watch (看)"}}', 'reward for / rewards program / risk and reward; reward employees / reward loyalty / financially rewarding', '[{"en":"Hard work will bring its own reward.","zh-TW":"努力工作自有回報。"},{"en":"The company has a generous rewards program.","zh-TW":"公司有優厚的獎勵計劃。"},{"en":"We reward employees for excellent performance.","zh-TW":"我們獎勵表現優秀的員工。"},{"en":"The career is both challenging and rewarding.","zh-TW":"這份職業既有挑戰性又有回報。"}]', '{"verb":"reward","adjective":"rewarding","noun":"reward"}', NULL, 2, 2655, 210),
(2656, 'rich', '/rɪtʃ/', 'adjective', '{"zh-TW":["富有的；豐富的"],"en":["having a lot of money","containing a lot of something"]}', NULL, 'rich in / get rich', '[{"en":"The region is rich in natural resources.","zh-TW":"這個地區自然資源豐富。"},{"en":"The data provides rich insights.","zh-TW":"數據提供了豐富的洞見。"}]', '{"adjective":"rich","noun":"riches","adverb":"richly","verb":"enrich"}', NULL, 1, 2656, NULL),
(2657, 'ride', '/raɪd/', 'verb', '{"zh-TW":["騎；乘坐"],"en":["to sit on and control","to travel in a vehicle"]}', NULL, 'ride sharing / free ride', '[{"en":"Ride-sharing apps reduced transport costs.","zh-TW":"共乘應用程式降低了交通成本。"},{"en":"There is no free ride in business.","zh-TW":"商場上沒有不勞而獲。"}]', '{"verb":"ride","noun":"ride","noun2":"rider"}', NULL, 1, 2657, NULL),
(2658, 'right', 'raɪt', 'adjective', '{"zh-TW":["正確的；合適的","右邊的"],"en":["correct or appropriate","in the correct position"]}', NULL, 'right approach/right person', '[{"en":"Make sure you choose the right candidate.","zh-TW":"確保您選擇了正確的候選人。"}]', '{"noun":"right","adverb":"rightly"}', NULL, 2, 2658, NULL),
(2659, 'rigid', '/ˈrɪdʒɪd/', 'adjective', '{"zh-TW":["嚴格的；僵硬的"],"en":["strict; not flexible"]}', '{"root":{"text":"rig","meaning":"stiff (僵硬)"}}', 'rigid rules / rigid structure / rigid schedule', '[{"en":"The company has very rigid policies.","zh-TW":"公司有非常嚴格的政策。"},{"en":"A rigid schedule leaves no room for creativity.","zh-TW":"僵化的日程不留創造空間。"}]', '{"noun":"rigidity","adverb":"rigidly"}', NULL, 2, 2659, NULL),
(2660, 'ring', '/rɪŋ/', 'verb', '{"zh-TW":["響鈴；打電話"],"en":["to make a sound like a bell","to telephone"]}', NULL, 'ring a bell / give someone a ring', '[{"en":"Does the name ring a bell?","zh-TW":"這個名字你聽起來熟悉嗎？"},{"en":"Give me a ring tomorrow morning.","zh-TW":"明天早上打電話給我。"}]', '{"verb":"ring","noun":"ring"}', NULL, 1, 2660, NULL),
(2661, 'rise', '/raɪz/', 'verb', '{"zh-TW":["上升；增加"],"en":["to move upward","to increase"]}', NULL, 'give rise to / on the rise', '[{"en":"Remote work is on the rise.","zh-TW":"遠端工作正在增加。"},{"en":"This gave rise to new regulations.","zh-TW":"這引發了新的法規。"}]', '{"verb":"rise","noun":"rise"}', NULL, 1, 2661, NULL),
(2662, 'risk', '/rɪsk/', 'noun', '{"zh-TW":["風險","冒...的風險"],"en":["the possibility of danger or loss","to expose to danger"]}', NULL, 'take a risk / risk management / at risk / risk assessment; risk losing / risk assessment / risk management / at risk', '[{"en":"Every investment involves some degree of risk.","zh-TW":"每項投資都涉及一定程度的風險。"},{"en":"We need a comprehensive risk assessment.","zh-TW":"我們需要全面的風險評估。"},{"en":"We risk losing market share if we don''t innovate.","zh-TW":"如不創新我們就有失去市佔率的風險。"},{"en":"Effective risk management is crucial.","zh-TW":"有效的風險管理至關重要。"}]', '{"verb":"risk","adjective":"risky","noun":"risk"}', NULL, 1, 2662, NULL),
(2663, 'river', '/ˈrɪvər/', 'noun', '{"zh-TW":["河流"],"en":["a large natural stream of water"]}', NULL, 'down the river / river bank', '[{"en":"The factory is located along the river.","zh-TW":"工廠坐落在河邊。"},{"en":"Don''t sell your team down the river.","zh-TW":"不要出賣你的團隊。"}]', '{"noun":"river","noun2":"riverside"}', NULL, 2, 2663, NULL),
(2664, 'road', '/roʊd/', 'noun', '{"zh-TW":["道路"],"en":["a path for vehicles and people"]}', NULL, 'on the road / road map', '[{"en":"Our sales team is always on the road.","zh-TW":"我們的業務團隊總是在外跑。"},{"en":"Here is our product road map.","zh-TW":"這是我們的產品路線圖。"}]', '{"noun":"road","noun2":"roadblock"}', NULL, 1, 2664, NULL),
(2665, 'roadmap', '/ˈroʊdmæp/', 'noun', '{"zh-TW":["路線圖；發展規劃"],"en":["a strategic plan outlining goals and the steps to achieve them"]}', NULL, 'create a roadmap / product roadmap / technology roadmap', '[{"en":"The board approved a three-year roadmap for digital transformation.","zh-TW":"董事會批准了數位轉型的三年路線圖。"},{"en":"The product roadmap guides the development team''s priorities.","zh-TW":"產品路線圖指導了開發團隊的優先事項。"}]', NULL, NULL, 3, 2665, NULL),
(2666, 'role', '/roʊl/', 'noun', '{"zh-TW":["角色；職責"],"en":["a function; a part played"]}', NULL, 'play a role / key role / role model / in the role of', '[{"en":"Technology plays a key role in our strategy.","zh-TW":"技術在我們策略中發揮關鍵作用。"},{"en":"She excels in her role as project lead.","zh-TW":"她在項目負責人的角色中表現出色。"}]', NULL, NULL, 1, 2666, 211),
(2667, 'rollout', '/ˈroʊlaʊt/', 'noun', '{"zh-TW":["推出；逐步部署"],"en":["the gradual introduction of a product or system to users"]}', NULL, 'phased rollout / nationwide rollout / rollout plan / product rollout', '[{"en":"The phased rollout allowed issues to be fixed before full launch.","zh-TW":"分階段推出允許在全面上市前修復問題。"},{"en":"The software rollout was completed across all offices in six weeks.","zh-TW":"軟體部署在六週內完成了所有辦公室的覆蓋。"}]', '{"verb":"roll out"}', NULL, 3, 2667, 927),
(2668, 'room', '/ruːm/', 'noun', '{"zh-TW":["房間；空間"],"en":["a section of a building","available space"]}', NULL, 'meeting room / room for improvement', '[{"en":"There is room for improvement.","zh-TW":"還有改善的空間。"},{"en":"Book the meeting room for 2 p.m.","zh-TW":"預訂下午2點的會議室。"}]', '{"noun":"room","adjective":"roomy"}', NULL, 1, 2668, NULL),
(2669, 'rotate', '/roʊˈteɪt/', 'verb', '{"zh-TW":["輪換；旋轉"],"en":["to move in a circle; to take turns"]}', '{"root":{"text":"rot","meaning":"wheel (輪)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'rotate duties / job rotation / rotating schedule', '[{"en":"Staff rotate between departments quarterly.","zh-TW":"員工每季度在部門間輪換。"},{"en":"The chairperson role rotates annually.","zh-TW":"主席一職每年輪換。"}]', '{"noun":"rotation","adjective":"rotating, rotational"}', NULL, 2, 2669, NULL),
(2670, 'rotation', '/roʊˈteɪʃən/', 'noun', '{"zh-TW":["輪調；輪換"],"en":["systematically moving employees between different roles or departments"]}', NULL, 'job rotation / rotation program / staff rotation', '[{"en":"Job rotation helps employees develop a broader skill set.","zh-TW":"職位輪調幫助員工培養更廣泛的技能。"},{"en":"The graduate program includes a rotation through all business units.","zh-TW":"研究生計劃包括在所有業務單位的輪調。"}]', '{"verb":"rotate","adjective":"rotating"}', NULL, 3, 2670, 928),
(2671, 'roughly', '/ˈrʌfli/', 'adverb', '{"zh-TW":["大約；粗略地"],"en":["approximately; in a rough way"]}', '{"root":{"text":"rough","meaning":"rough (粗糙)"},"suffix":{"text":"-ly","meaning":"副詞後綴"}}', 'roughly equal / roughly speaking / roughly estimated', '[{"en":"The project will cost roughly $100,000.","zh-TW":"項目大約花費十萬美元。"},{"en":"Roughly 60% of staff attended.","zh-TW":"大約60%的員工出席了。"}]', '{"adjective":"rough"}', NULL, 3, 2671, NULL),
(2672, 'round', '/raʊnd/', 'noun', '{"zh-TW":["一輪；回合"],"en":["a series or cycle","approximately"]}', NULL, 'round of funding / year-round', '[{"en":"The startup raised a second round of funding.","zh-TW":"新創公司完成了第二輪融資。"},{"en":"The resort is open year-round.","zh-TW":"度假村全年開放。"}]', '{"noun":"round","adjective":"round","verb":"round","adverb":"around"}', NULL, 2, 2672, NULL),
(2673, 'round-the-clock', '/ˌraʊnd ðə ˈklɒk/', 'adjective', '{"zh-TW":["全天候的；24小時的"],"en":["continuing or available at all times, day and night"]}', NULL, 'round-the-clock support / round-the-clock operations', '[{"en":"The call center provides round-the-clock customer support.","zh-TW":"呼叫中心提供全天候客戶支援。"},{"en":"Emergency services operate on a round-the-clock basis.","zh-TW":"緊急服務全天候運作。"}]', NULL, NULL, 5, 2673, NULL),
(2674, 'roundtrip', '/ˈraʊndtrɪp/', 'noun', '{"zh-TW":["來回旅程"],"en":["a journey to a place and back again"]}', NULL, 'roundtrip ticket / roundtrip fare', '[{"en":"A roundtrip ticket is usually cheaper than two one-way tickets.","zh-TW":"來回票通常比兩張單程票便宜。"},{"en":"We booked roundtrip flights to London.","zh-TW":"我們預訂了倫敦的來回機票。"}]', NULL, NULL, 3, 2674, NULL),
(2675, 'router', '/ˈraʊtər/', 'noun', '{"zh-TW":["路由器"],"en":["a device that directs internet traffic"]}', NULL, 'wireless router / router settings', '[{"en":"Restart the router to fix the connection.","zh-TW":"重啟路由器來修復連線。"},{"en":"The wireless router covers the whole house.","zh-TW":"無線路由器覆蓋整棟房子。"}]', NULL, NULL, 2, 2675, NULL),
(2676, 'routine', '/ruːˈtiːn/', 'noun', '{"zh-TW":["例行公事；日常工作","例行的；常規的"],"en":["a regular way of doing things","regular; done as part of normal procedure"]}', NULL, 'daily routine / routine maintenance / routine procedure; routine check / routine inspection / routine maintenance', '[{"en":"Routine maintenance is scheduled for Sunday.","zh-TW":"例行維護安排在週日。"},{"en":"It became part of the daily routine.","zh-TW":"它成為了日常工作的一部分。"},{"en":"This is just a routine inspection.","zh-TW":"這只是例行檢查。"},{"en":"Routine maintenance keeps equipment running.","zh-TW":"例行維護使設備正常運行。"}]', '{"adjective":"routine","adverb":"routinely","noun":"routine"}', NULL, 3, 2676, 212),
(2677, 'RSU', '/ˌɑːr es ˈjuː/', 'noun', '{"zh-TW":["限制性股票單位"],"en":["restricted stock unit; shares awarded to employees that vest over time"]}', NULL, 'RSU vesting / RSU award / receive RSUs', '[{"en":"She received 500 RSUs as part of her compensation package.","zh-TW":"她收到了500個限制性股票單位作為薪酬方案的一部分。"},{"en":"RSUs provide ownership stake without requiring upfront purchase.","zh-TW":"限制性股票單位提供所有權份額，無需預先購買。"}]', '{"full form":"restricted stock unit"}', NULL, 1, 2677, NULL),
(2678, 'RSVP', '/ɑːr ɛs viː piː/', 'verb', '{"zh-TW":["回覆邀請"],"en":["to respond to an invitation"]}', NULL, 'please RSVP / RSVP by Friday', '[{"en":"Please RSVP by Friday to confirm your attendance.","zh-TW":"請在週五前回覆以確認您的出席。"},{"en":"We need to finalize the guest list, so RSVP is required.","zh-TW":"我們需要確定賓客名單，因此請回覆邀請。"}]', NULL, NULL, 1, 2678, NULL),
(2679, 'rule', '/ruːl/', 'noun', '{"zh-TW":["規則；法規"],"en":["an official instruction"]}', NULL, 'follow the rules / rule out / as a rule / rule of thumb', '[{"en":"All participants must follow the rules.","zh-TW":"所有參與者必須遵守規則。"},{"en":"We cannot rule out the possibility.","zh-TW":"我們不能排除這種可能性。"}]', '{"verb":"rule","noun":"ruler, ruling"}', NULL, 1, 2679, NULL),
(2680, 'run', '/rʌn/', 'verb', '{"zh-TW":["【主要意義-動詞】跑；運行","【次要意義-動詞】管理；經營（業務）","【次要意義-名詞】一連串（事件）；連續期間","【次要意義-名詞】（機器）運作期間"],"en":["[primary] to move quickly on foot; to operate","[secondary - verb] to manage or operate a business or organization","[secondary - noun] a continuous series or period","[secondary - noun] the operation of a machine or system"]}', NULL, 'run a business / run a meeting / in the long run / a run on the bank / on the run', '[{"en":"She has run the family business for over 15 years.","zh-TW":"她已經經營家族企業超過15年了。"},{"en":"In the long run, investing in training pays off for companies.","zh-TW":"從長遠來看，投資培訓對公司來說是值得的。"},{"en":"The factory had a production run of 50,000 units last month.","zh-TW":"上個月工廠的生產批次達到了5萬件。"}]', '{"noun":"runner, running","adjective":"running"}', '動詞 run = 「管理/經營」是 TOEIC 極高頻用法，in the long run（從長遠來看）是必考片語，a production run（生產批次）出現在製造業文章中。', 1, 2680, NULL),
(2681, 'runway', '/ˈrʌnweɪ/', 'noun', '{"zh-TW":["資金跑道；可支撐時間"],"en":["the amount of time a startup can operate before running out of cash"]}', NULL, 'extend the runway / 12 months of runway / calculate runway', '[{"en":"With $3M in the bank and a $250K burn rate, they had 12 months of runway.","zh-TW":"銀行有300萬美元，燒錢速度25萬美元，他們有12個月的資金跑道。"},{"en":"Raising a new round extended the company''s runway by two years.","zh-TW":"新一輪融資將公司的資金跑道延長了兩年。"}]', NULL, NULL, 2, 2681, NULL),
(2682, 'résumé', '/ˈrezjʊmeɪ/', 'noun', '{"zh-TW":["履歷；簡歷"],"en":["a document summarizing an individual''s work experience and qualifications"]}', NULL, 'submit a résumé / update your résumé / résumé review', '[{"en":"She tailored her résumé to highlight relevant experience.","zh-TW":"她客製化了簡歷以突出相關經驗。"},{"en":"A strong résumé increases the chance of landing an interview.","zh-TW":"一份強力的履歷提高了獲得面試機會的可能性。"}]', '{"alternative":"CV (curriculum vitae)","plural":"résumés"}', NULL, 2, 2682, NULL),
(2683, 'SaaS', '/sæs/', 'noun', '{"zh-TW":["軟體即服務"],"en":["software as a service; cloud-based software accessed via subscription"]}', NULL, 'SaaS platform / SaaS model / SaaS product / switch to SaaS', '[{"en":"The company switched from on-premise software to a SaaS solution.","zh-TW":"公司從本地軟體切換到了SaaS解決方案。"},{"en":"SaaS products offer automatic updates and lower upfront costs.","zh-TW":"SaaS產品提供自動更新和更低的前期成本。"}]', '{"full form":"software as a service"}', NULL, 1, 2683, NULL),
(2684, 'sabbatical', '/səˈbætɪkəl/', 'noun', '{"zh-TW":["休假；研究假"],"en":["an extended period of leave granted to an employee for rest or study"]}', NULL, 'sabbatical leave / take a sabbatical / paid sabbatical', '[{"en":"She took a six-month sabbatical to write her book.","zh-TW":"她請了六個月的休假來寫書。"},{"en":"The company offers sabbaticals after ten years of service.","zh-TW":"公司為服務滿十年的員工提供研究假。"}]', '{"adjective":"sabbatical"}', NULL, 4, 2684, NULL),
(2685, 'sacrifice', '/ˈsækrɪfaɪs/', 'noun, verb', '{"zh-TW":["犧牲；獻祭","犧牲；放棄"],"en":["an act of giving up something valued","to give up something important"]}', NULL, 'make a sacrifice / sacrifice for', '[{"en":"She made a great sacrifice for her family.","zh-TW":"她為家人做出了巨大的犧牲。"},{"en":"He sacrificed his career for his children.","zh-TW":"他為了孩子犧牲了自己的事業。"}]', '{"noun":"sacrifice","verb":"sacrifice","adjective":"sacrificial"}', NULL, 3, 2685, NULL),
(2686, 'sad', '/sæd/', 'adjective', '{"zh-TW":["悲傷的；令人遺憾的"],"en":["feeling unhappy","unfortunate"]}', NULL, 'sad news / sadly', '[{"en":"I have sad news about the layoffs.","zh-TW":"我有關於裁員的壞消息。"},{"en":"Sadly, the branch will close.","zh-TW":"不幸的是，分公司將關閉。"}]', '{"adjective":"sad","noun":"sadness","adverb":"sadly","verb":"sadden"}', NULL, 1, 2686, NULL),
(2687, 'safe', '/seɪf/', 'adjective', '{"zh-TW":["安全的"],"en":["protected from danger"]}', NULL, 'safe and sound / play it safe', '[{"en":"All employees arrived safe and sound.","zh-TW":"所有員工都安全抵達。"},{"en":"Let''s play it safe with this investment.","zh-TW":"這項投資我們保守一點。"}]', '{"adjective":"safe","noun":"safety","adverb":"safely","verb":"safeguard"}', NULL, 1, 2687, NULL),
(2688, 'safeguard', '/ˈseɪfɡɑːrd/', 'noun, verb', '{"zh-TW":["保障措施；防護","保護；防衛"],"en":["a measure taken to protect","to protect from harm"]}', NULL, 'safeguard against / safeguard interests', '[{"en":"We need safeguards against data breaches.","zh-TW":"我們需要防範資料洩露的保障措施。"},{"en":"The policy safeguards employees'' rights.","zh-TW":"該政策保障了員工的權利。"}]', '{"noun":"safeguard","verb":"safeguard"}', NULL, 3, 2688, 929),
(2689, 'salary', '/ˈsæləri/', 'noun', '{"zh-TW":["薪水；薪資"],"en":["a fixed regular payment for work"]}', NULL, 'annual salary / salary increase / base salary', '[{"en":"Her annual salary is $80,000.","zh-TW":"她的年薪是八萬美元。"},{"en":"Employees received a 5% salary increase.","zh-TW":"員工獲得了5%的加薪。"}]', '{"noun":"salary","adjective":"salaried"}', NULL, 2, 2689, NULL),
(2690, 'sale', '/seɪl/', 'noun', '{"zh-TW":["銷售；特賣"],"en":["the act of selling","a period when goods are sold at reduced prices"]}', '{"root":{"text":"sale","meaning":"sell (賣)"},"logic":"販售的行為或特賣活動。"}', 'on sale / sales figures / for sale', '[{"en":"The house is for sale.","zh-TW":"這棟房子出售中。"},{"en":"Winter coats are on sale this week.","zh-TW":"冬季外套本週特價。"}]', '{"noun":"salesperson","verb":"sell"}', NULL, 1, 2690, NULL),
(2691, 'sales', 'seɪlz', 'noun', '{"zh-TW":["銷售額；銷售量","銷售"],"en":["the total money from selling","the activity of selling"]}', NULL, 'sales target/sales team', '[{"en":"The sales team exceeded its quarterly target.","zh-TW":"銷售團隊超過了季度目標。"}]', '{"verb":"sell","adjective":"sales-oriented"}', NULL, 2, 2691, NULL),
(2692, 'sample', '/ˈsæmpl/', 'noun, verb', '{"zh-TW":["樣品；樣本","取樣；品嚐"],"en":["a small part representing the whole","to take a sample of"]}', NULL, 'free sample / sample size / random sample', '[{"en":"We collected a random sample of 500 customers.","zh-TW":"我們隨機抽樣了500位顧客。"},{"en":"Would you like to sample the new product?","zh-TW":"您想試用新產品嗎？"}]', '{"noun":"sample, sampling","verb":"sample"}', NULL, 2, 2692, NULL),
(2693, 'sanction', '/ˈsæŋkʃən/', 'noun', '{"zh-TW":["制裁；許可","制裁；處罰","批准；認可"],"en":["a penalty imposed on a country; official approval","a penalty for breaking a law","to give official permission"]}', NULL, 'economic sanctions / impose sanctions; impose sanctions / economic sanctions / lift sanctions', '[{"en":"The country faces economic sanctions.","zh-TW":"該國面臨經濟制裁。"},{"en":"Sanctions were imposed on the regime.","zh-TW":"對該政權實施了制裁。"},{"en":"The government imposed economic sanctions.","zh-TW":"政府實施了經濟制裁。"},{"en":"The plan was sanctioned by the board.","zh-TW":"該計畫已獲董事會批准。"}]', '{"verb":"sanction","noun":"sanction"}', NULL, 3, 2693, 930),
(2694, 'sanctions', '/ˈsæŋkʃənz/', 'noun', '{"zh-TW":["制裁；處罰"],"en":["penalties imposed by governments on other countries or entities"]}', NULL, 'impose sanctions / lift sanctions / economic sanctions', '[{"en":"Economic sanctions were imposed on the country for treaty violations.","zh-TW":"因違反條約，對該國實施了經濟制裁。"},{"en":"Sanctions disrupted the company''s ability to do business abroad.","zh-TW":"制裁干擾了公司在海外的業務能力。"}]', '{"verb":"sanction","singular":"sanction"}', NULL, 3, 2694, NULL),
(2695, 'satellite', '/ˈsætəlaɪt/', 'noun', '{"zh-TW":["衛星"],"en":["an object orbiting a planet; a device in space"]}', NULL, 'satellite TV / communication satellite', '[{"en":"The satellite orbits the Earth.","zh-TW":"衛星繞地球運行。"},{"en":"We get internet via satellite.","zh-TW":"我們透過衛星上網。"}]', NULL, NULL, 3, 2695, NULL),
(2696, 'satisfy', '/ˈsætɪsfaɪ/', 'verb', '{"zh-TW":["滿足；使滿意","符合（要求）"],"en":["to fulfill the needs or desires of","to meet requirements"]}', '{"suffix":{"text":"-fy","meaning":"使..."}}', 'satisfy demands / satisfy customers / satisfy requirements', '[{"en":"The results satisfied all stakeholders.","zh-TW":"結果讓所有利害關係人都滿意。"},{"en":"The candidate satisfies all the requirements.","zh-TW":"這位候選人符合所有要求。"}]', '{"noun":"satisfaction","verb":"satisfy","adjective":"satisfactory, satisfied, satisfying"}', NULL, 3, 2696, NULL),
(2697, 'sauna', '/ˈsɔːnə/', 'noun', '{"zh-TW":["桑拿浴室；三溫暖"],"en":["a room heated to a high temperature for relaxation"]}', NULL, 'use the sauna / hotel sauna', '[{"en":"The hotel''s sauna is open from 6 am to 10 pm.","zh-TW":"飯店的三溫暖從早上6點開放至晚上10點。"},{"en":"A sauna session can help you relax after a long flight.","zh-TW":"桑拿浴有助於長途飛行後放鬆。"}]', NULL, NULL, 2, 2697, NULL),
(2698, 'save', '/seɪv/', 'verb', '{"zh-TW":["節省；儲蓄","拯救；保存"],"en":["to keep money for future use","to rescue from danger"]}', NULL, 'save money / save time / save energy', '[{"en":"She saves 20% of her income every month.","zh-TW":"她每個月存下收入的20%。"},{"en":"The new system saves us a lot of time.","zh-TW":"新系統為我們節省了大量時間。"}]', '{"noun":"savings, saver","verb":"save"}', NULL, 1, 2698, NULL),
(2699, 'say', 'seɪ', 'verb', '{"zh-TW":["說；表示","聲稱"],"en":["to speak words","to express in words"]}', NULL, 'say something/that', '[{"en":"What did the manager say?","zh-TW":"經理說了什麼？"}]', '{"noun":"saying"}', NULL, 1, 2699, NULL);
