(2700, 'scalability', '/ˌskeɪləˈbɪlɪti/', 'noun', '{"zh-TW":["可擴展性；擴展能力"],"en":["the ability of a system or business to grow efficiently"]}', NULL, 'business scalability / scalability of the model', '[{"en":"The platform was designed with scalability in mind.","zh-TW":"該平台設計時考慮了可擴展性。"},{"en":"Scalability is essential for any startup aiming to grow.","zh-TW":"可擴展性對任何目標成長的新創公司都至關重要。"}]', '{"adjective":"scalable","verb":"scale"}', NULL, 4, 2700, 810),
(2701, 'scalable', '/ˈskeɪləbl/', 'adjective', '{"zh-TW":["可擴展的；可規模化的"],"en":["able to grow or expand efficiently to meet increasing demand"]}', NULL, 'scalable business model / scalable solution / highly scalable', '[{"en":"The SaaS platform is highly scalable and can handle millions of users.","zh-TW":"SaaS平台具有高度可擴展性，可以處理數百萬用戶。"},{"en":"Investors seek scalable business models with large addressable markets.","zh-TW":"投資者尋求具有大型可觸達市場的可擴展商業模式。"}]', '{"noun":"scalability","verb":"scale"}', NULL, 3, 2701, NULL),
(2702, 'scale', '/skeɪl/', 'noun, verb', '{"zh-TW":["規模；比例","擴大規模；攀登"],"en":["the size or extent of something","to increase in size"]}', NULL, 'on a large scale / economies of scale / scale up', '[{"en":"The company plans to scale up production.","zh-TW":"公司計劃擴大生產規模。"},{"en":"The project was carried out on a large scale.","zh-TW":"該專案是大規模進行的。"}]', '{"noun":"scale","verb":"scale","adjective":"scalable"}', NULL, 2, 2702, NULL),
(2703, 'scan', '/skæn/', 'verb, noun', '{"zh-TW":["掃描；瀏覽","掃描"],"en":["to examine quickly","a medical or electronic examination"]}', NULL, 'scan a document / brain scan / scan for errors', '[{"en":"Please scan the document and email it.","zh-TW":"請掃描文件並用電子郵件發送。"},{"en":"She scanned the report for key findings.","zh-TW":"她快速瀏覽了報告的主要發現。"}]', '{"noun":"scan, scanner","verb":"scan"}', NULL, 1, 2703, NULL),
(2704, 'scarce', '/skers/', 'adjective', '{"zh-TW":["稀少的；缺乏的"],"en":["insufficient for the demand; not enough"]}', NULL, 'scarce resources / increasingly scarce', '[{"en":"Clean water is scarce in many regions.","zh-TW":"乾淨的水在許多地區很稀缺。"},{"en":"Skilled workers are becoming increasingly scarce.","zh-TW":"技術工人越來越稀缺。"}]', '{"noun":"scarcity","adjective":"scarce","adverb":"scarcely"}', NULL, 2, 2704, NULL),
(2705, 'scarcity', '/ˈskeərsɪti/', 'noun', '{"zh-TW":["稀缺；稀缺性"],"en":["the limited availability of a resource relative to demand"]}', NULL, 'scarcity of resources / create scarcity / scarcity principle', '[{"en":"Scarcity of skilled engineers pushed salaries higher.","zh-TW":"技術工程師的稀缺推高了薪資。"},{"en":"The marketing campaign used scarcity to drive urgency.","zh-TW":"行銷活動利用稀缺性製造緊迫感。"}]', '{"adjective":"scarce","adverb":"scarcely"}', NULL, 3, 2705, NULL),
(2706, 'scenario', '/sɪˈnærioʊ/', 'noun', '{"zh-TW":["情境；劇本","可能的情況"],"en":["a possible sequence of events","a written outline of a story"]}', NULL, 'worst-case scenario / best-case scenario / likely scenario', '[{"en":"In the worst-case scenario, we lose 10% revenue.","zh-TW":"在最壞的情況下，我們會損失10%的收入。"},{"en":"Let''s consider various scenarios before deciding.","zh-TW":"讓我們在決定前考慮各種情境。"}]', '{"noun":"scenario"}', NULL, 3, 2706, NULL),
