(2708, 'scheme', '/skiːm/', 'noun, verb', '{"zh-TW":["計畫；方案","策劃；圖謀"],"en":["a systematic plan or arrangement","to make plans secretly"]}', NULL, 'color scheme / pension scheme / scheme to do sth.', '[{"en":"The company launched a new training scheme.","zh-TW":"公司推出了新的培訓方案。"},{"en":"They schemed to take over the business.","zh-TW":"他們密謀接管這家公司。"}]', '{"noun":"scheme, schemer","verb":"scheme"}', NULL, 2, 2708, NULL),
