(2711, 'science', '/ˈsaɪəns/', 'noun', '{"zh-TW":["科學"],"en":["the study of the natural world through observation"]}', NULL, 'data science / computer science', '[{"en":"Data science drives our decisions.","zh-TW":"數據科學驅動我們的決策。"},{"en":"She has a degree in computer science.","zh-TW":"她有電腦科學學位。"}]', '{"noun":"science","noun2":"scientist","adjective":"scientific","adverb":"scientifically"}', NULL, 3, 2711, NULL),
(2712, 'scope', '/skoʊp/', 'noun', '{"zh-TW":["範圍；領域","機會；餘地"],"en":["the range of a subject or activity","opportunity for action"]}', NULL, 'scope of work / beyond the scope / within scope', '[{"en":"This issue is beyond the scope of our project.","zh-TW":"這個問題超出了我們專案的範圍。"},{"en":"There is scope for improvement.","zh-TW":"仍有改進的空間。"}]', '{"noun":"scope"}', NULL, 2, 2712, NULL),
(2713, 'score', '/skɔːr/', 'noun', '{"zh-TW":["得分；分數"],"en":["the number of points in a game"]}', NULL, 'final score / high score', '[{"en":"The final score was 3-2.","zh-TW":"最終比分是3比2。"},{"en":"She got a high score on the test.","zh-TW":"她考試得了高分。"}]', '{"verb":"score","noun2":"scoreboard"}', NULL, 2, 2713, NULL),
