(2715, 'screen', '/skriːn/', 'noun, verb', '{"zh-TW":["螢幕；屏幕","篩選；審查"],"en":["a display surface","to examine or check systematically"]}', NULL, 'screen candidates / on screen / screening process', '[{"en":"All applicants are screened before the interview.","zh-TW":"所有應徵者在面試前都會經過篩選。"},{"en":"The presentation will appear on screen.","zh-TW":"簡報將顯示在螢幕上。"}]', '{"noun":"screen, screening","verb":"screen"}', NULL, 2, 2715, NULL),
(2716, 'screening', '/ˈskriːnɪŋ/', 'noun', '{"zh-TW":["篩選；審查","放映"],"en":["the testing or examining of a group","the showing of a film"]}', NULL, 'background screening / screening process / health screening', '[{"en":"All candidates undergo a background screening.","zh-TW":"所有候選人都會接受背景審查。"},{"en":"The screening process takes about two weeks.","zh-TW":"篩選過程大約需要兩週。"}]', '{"noun":"screening, screen","verb":"screen"}', NULL, 3, 2716, NULL),
(2717, 'Scrum', '/skrʌm/', 'noun', '{"zh-TW":["Scrum框架；敏捷開發框架"],"en":["an agile framework for managing and completing complex projects"]}', NULL, 'Scrum framework / Scrum master / Scrum team / daily Scrum', '[{"en":"The development team adopted Scrum to improve delivery speed.","zh-TW":"開發團隊採用Scrum框架以提高交付速度。"},{"en":"The daily Scrum is a 15-minute standup meeting.","zh-TW":"每日Scrum是一個15分鐘的站立會議。"}]', '{"noun":"Scrum master"}', NULL, 2, 2717, NULL),
(2718, 'scrutiny', '/ˈskruːtəni/', 'noun', '{"zh-TW":["仔細檢查；審查"],"en":["careful and thorough examination"]}', NULL, 'under scrutiny / public scrutiny / close scrutiny', '[{"en":"The company''s finances are under close scrutiny.","zh-TW":"公司的財務正在接受仔細審查。"},{"en":"His actions came under public scrutiny.","zh-TW":"他的行為受到了公眾的審視。"}]', '{"noun":"scrutiny","verb":"scrutinize"}', NULL, 3, 2718, NULL),
(2719, 'sculpture', '/ˈskʌlptʃər/', 'noun', '{"zh-TW":["雕塑"],"en":["a three-dimensional work of art"]}', '{"root":{"text":"sculpt","meaning":"carve (雕刻)"},"suffix":{"text":"-ure","meaning":"result (結果)"},"logic":"雕刻的結果，即「雕塑」。"}', 'marble sculpture / modern sculpture', '[{"en":"The sculpture was made entirely of recycled metal.","zh-TW":"這座雕塑完全由回收金屬製成。"},{"en":"There is a famous sculpture in the park.","zh-TW":"公園裡有一座著名的雕塑。"}]', '{"verb":"sculpt","noun":"sculptor"}', NULL, 3, 2719, NULL),
(2720, 'sea', '/siː/', 'noun', '{"zh-TW":["海"],"en":["a large body of saltwater"]}', NULL, 'by sea / at sea', '[{"en":"Goods are shipped by sea.","zh-TW":"貨物經由海運運送。"},{"en":"I am still at sea about the new policy.","zh-TW":"我對新政策還摸不著頭緒。"}]', '{"noun":"sea","adjective":"seaside","noun2":"seaport"}', NULL, 1, 2720, NULL),
(2721, 'season', '/ˈsiːzən/', 'noun', '{"zh-TW":["季節；賽季"],"en":["one of the four periods of the year"]}', NULL, 'in season / off season', '[{"en":"Winter is my favorite season.","zh-TW":"冬天是我最喜歡的季節。"},{"en":"The team had a great season.","zh-TW":"這支球隊賽季表現出色。"}]', '{"adjective":"seasonal"}', NULL, 2, 2721, NULL),
(2722, 'seasoning', '/ˈsiːzənɪŋ/', 'noun', '{"zh-TW":["調味料；調味"],"en":["salt, herbs, or spices added to food"]}', NULL, 'add seasoning / light seasoning', '[{"en":"The chef adjusted the seasoning before serving.","zh-TW":"主廚在上菜前調整了調味。"},{"en":"This dish requires very little seasoning.","zh-TW":"這道菜只需要很少的調味料。"}]', '{"verb":"season","adjective":"seasoned"}', NULL, 3, 2722, NULL),
(2723, 'seat', '/siːt/', 'noun', '{"zh-TW":["座位"],"en":["a place to sit"]}', NULL, 'take a seat / window seat', '[{"en":"Please take a seat.","zh-TW":"請坐。"},{"en":"I prefer a window seat on flights.","zh-TW":"搭飛機時我偏好靠窗的座位。"}]', '{"noun":"seat","verb":"seat","noun2":"seating"}', NULL, 1, 2723, NULL),
(2724, 'secondment', '/ˈsekəndmənt/', 'noun', '{"zh-TW":["借調；臨時派遣"],"en":["the temporary transfer of an employee to another role or organization"]}', NULL, 'secondment opportunity / on secondment / secondment agreement', '[{"en":"She went on a six-month secondment to the Singapore office.","zh-TW":"她被借調到新加坡辦公室工作六個月。"},{"en":"A secondment can broaden an employee''s skills and network.","zh-TW":"借調可以拓寬員工的技能和人際網絡。"}]', '{"verb":"second"}', NULL, 4, 2724, NULL),
(2725, 'secret', '/ˈsiːkrɪt/', 'noun', '{"zh-TW":["秘密"],"en":["something kept hidden"]}', NULL, 'trade secret / keep a secret', '[{"en":"That recipe is a trade secret.","zh-TW":"那個配方是商業機密。"},{"en":"The key to success is no secret.","zh-TW":"成功的關鍵不是秘密。"}]', '{"noun":"secret","adjective":"secret","noun2":"secrecy","adverb":"secretly"}', NULL, 2, 2725, NULL),
