(2728, 'secure', '/sɪˈkjʊr/', 'adjective, verb', '{"zh-TW":["安全的；穩固的","獲得；確保"],"en":["safe from threat","to obtain or achieve"]}', NULL, 'secure a deal / secure environment / job security', '[{"en":"We secured a major contract with the client.","zh-TW":"我們與客戶簽下了一份大合約。"},{"en":"The building has a secure entrance.","zh-TW":"這棟建築有一個安全的入口。"}]', '{"noun":"security","verb":"secure","adjective":"secure, insecure","adverb":"securely"}', NULL, 2, 2728, 213),
(2729, 'securities', '/sɪˈkjʊərɪtiz/', 'noun', '{"zh-TW":["證券"],"en":["tradeable financial instruments including stocks and bonds"]}', NULL, 'invest in securities / trade securities / issue securities', '[{"en":"The fund invests in a mix of equities and fixed income securities.","zh-TW":"基金投資於股票和固定收益證券的組合。"},{"en":"Securities must be registered before they can be sold to the public.","zh-TW":"證券在向公眾出售前必須進行登記。"}]', '{"singular":"security","adjective":"secured"}', NULL, 4, 2729, NULL),
(2730, 'securitization', '/sɪˌkjʊərɪtɪˈzeɪʃən/', 'noun', '{"zh-TW":["資產證券化"],"en":["pooling financial assets and selling them as securities to investors"]}', NULL, 'mortgage securitization / asset securitization / securitization market', '[{"en":"Securitization allows banks to free up capital for new loans.","zh-TW":"資產證券化使銀行能夠釋放資本用於新貸款。"},{"en":"The securitization of subprime mortgages contributed to the financial crisis.","zh-TW":"次級抵押貸款的證券化加劇了金融危機。"}]', '{"verb":"securitize","adjective":"securitized"}', NULL, 5, 2730, NULL),
(2731, 'see', 'siː', 'verb', '{"zh-TW":["看見；理解","確保"],"en":["to perceive with eyes","to understand"]}', NULL, 'see a problem/results', '[{"en":"I see your point clearly.","zh-TW":"我清楚地理解您的觀點。"}]', '{"noun":"sight","adjective":"sighted"}', NULL, 1, 2731, NULL),
(2732, 'seek', '/siːk/', 'verb', '{"zh-TW":["尋求；追求","試圖"],"en":["to try to find or obtain","to attempt"]}', NULL, 'seek advice / seek approval / seek opportunities', '[{"en":"We are seeking qualified candidates for the position.","zh-TW":"我們正在尋找合格的職位候選人。"},{"en":"She sought advice from a financial consultant.","zh-TW":"她向財務顧問尋求建議。"}]', '{"noun":"seeker","verb":"seek"}', NULL, 1, 2732, NULL),
