(2734, 'seize', '/siːz/', 'verb', '{"zh-TW":["抓住；奪取","沒收"],"en":["to take hold of suddenly","to confiscate"]}', NULL, 'seize an opportunity / seize control / seize assets', '[{"en":"You should seize this opportunity immediately.","zh-TW":"你應該立即抓住這個機會。"},{"en":"Authorities seized illegal goods at the border.","zh-TW":"當局在邊境沒收了非法貨物。"}]', '{"noun":"seizure","verb":"seize"}', NULL, 2, 2734, NULL),
