(2737, 'sell', '/sɛl/', 'verb', '{"zh-TW":["賣；銷售"],"en":["to exchange for money"]}', NULL, 'best-selling / sell out', '[{"en":"This is our best-selling product.","zh-TW":"這是我們最暢銷的產品。"},{"en":"Tickets sold out in two hours.","zh-TW":"票兩小時內就賣完了。"}]', '{"verb":"sell","noun":"seller","noun2":"sale","noun3":"sales"}', NULL, 1, 2737, NULL),
(2738, 'SEM', '/ˌes iː ˈem/', 'noun', '{"zh-TW":["搜尋引擎行銷"],"en":["search engine marketing; paid advertising in search engine results"]}', NULL, 'SEM campaign / SEM strategy / implement SEM', '[{"en":"SEM complements SEO to maximize search visibility.","zh-TW":"SEM補充了SEO以最大化搜尋可見性。"},{"en":"She managed a $50,000 monthly SEM budget.","zh-TW":"她管理著每月5萬美元的SEM預算。"}]', '{"full form":"search engine marketing"}', NULL, 1, 2738, NULL),
(2739, 'semester', '/sɪˈmɛstər/', 'noun', '{"zh-TW":["學期"],"en":["half of the school year","a half-year term in a school or university"]}', NULL, 'fall semester / spring semester; fall semester / spring semester / per semester', '[{"en":"The fall semester starts in August.","zh-TW":"秋季學期八月開始。"},{"en":"I''m taking five courses this semester.","zh-TW":"這學期我修了五門課。"},{"en":"The course runs for one semester.","zh-TW":"這門課程為期一個學期。"},{"en":"Registration for next semester starts in November.","zh-TW":"下學期的註冊在十一月開始。"}]', '{"noun":"semester"}', NULL, 3, 2739, NULL),
(2740, 'seminar', '/ˈsɛmɪnɑːr/', 'noun', '{"zh-TW":["研討會；小組討論課"],"en":["a small class for discussion or advanced study"]}', NULL, 'attend a seminar / academic seminar', '[{"en":"The seminar focused on global economic trends.","zh-TW":"研討會聚焦於全球經濟趨勢。"},{"en":"Participation in the seminar counts toward your final grade.","zh-TW":"參與研討會計入您的最終成績。"}]', NULL, NULL, 3, 2740, NULL),
