(2743, 'senior', '/ˈsiːnjər/', 'adjective, noun', '{"zh-TW":["資深的；年長的","前輩；上級"],"en":["higher in rank or longer in service","an older or higher-ranking person"]}', NULL, 'senior manager / senior staff / senior position', '[{"en":"She was promoted to senior manager.","zh-TW":"她被提升為資深經理。"},{"en":"Senior employees receive additional benefits.","zh-TW":"資深員工享有額外福利。"}]', '{"noun":"seniority, senior","adjective":"senior"}', NULL, 2, 2743, 452),
