(2746, 'sensitive', '/ˈsensɪtɪv/', 'adjective', '{"zh-TW":["敏感的；善感的","敏感的；靈敏的","機密的"],"en":["easily affected by others'' feelings or external conditions","easily affected or offended","requiring careful handling"]}', '{"root":{"text":"sens","meaning":"feel (感覺)"},"suffix":{"text":"-itive","meaning":"tending to (傾向)"},"logic":"容易感受到的，即「敏感的」。"}', 'sensitive issue / sensitive skin; sensitive information / sensitive issue / price-sensitive', '[{"en":"She is very sensitive to criticism.","zh-TW":"她對批評很敏感。"},{"en":"This is a sensitive topic.","zh-TW":"這是一個敏感的話題。"},{"en":"This is sensitive information; do not share it.","zh-TW":"這是機密資訊，不要分享。"},{"en":"He is very sensitive to criticism.","zh-TW":"他對批評非常敏感。"}]', '{"noun":"sensitivity","verb":"sensitize","adjective":"sensitive, insensitive","adverb":"sensitively"}', NULL, 3, 2746, NULL),
(2747, 'sensor', '/ˈsɛnsər/', 'noun', '{"zh-TW":["感應器"],"en":["a device that detects changes in the environment"]}', NULL, 'motion sensor / temperature sensor', '[{"en":"The motion sensor turns on the light.","zh-TW":"動作感應器會開燈。"},{"en":"Modern cars have many sensors.","zh-TW":"現代汽車有很多感應器。"}]', NULL, NULL, 2, 2747, NULL),
