(2749, 'separate', '/ˈsepəreɪt/', 'verb, adjective', '{"zh-TW":["分開；區分","個別的；獨立的"],"en":["to divide or keep apart","forming a unit by itself"]}', NULL, 'separate from / separate issue / keep separate', '[{"en":"Please keep personal and business expenses separate.","zh-TW":"請將個人和商業支出分開。"},{"en":"The two departments operate as separate entities.","zh-TW":"這兩個部門作為獨立的實體運作。"}]', '{"noun":"separation","verb":"separate","adjective":"separate","adverb":"separately"}', NULL, 3, 2749, 453);
