(2780, 'shrink', '/ʃrɪŋk/', 'verb', '{"zh-TW":["縮小；萎縮"],"en":["to become smaller in size or amount"]}', NULL, 'shrink in size / shrink the budget / profit margins shrink', '[{"en":"The economy shrank by 2% last quarter.","zh-TW":"上季度經濟萎縮了2%。"},{"en":"Rising costs have shrunk profit margins.","zh-TW":"成本上升壓縮了利潤率。"}]', '{"noun":"shrinkage","verb":"shrink"}', NULL, 2, 2780, NULL),
